create or replace function ayngaran_private.write_rows(p_owner uuid, p_changes jsonb) returns void language plpgsql security invoker set search_path='' as $$ begin
insert into public.ayngaran_settings as existing ("owner_id","position","extras","name","address","phone","currency","receipt_note","tax_rate")
select p_owner,r."position",r."extras",r."name",r."address",r."phone",r."currency",r."receipt_note",r."tax_rate" from jsonb_populate_recordset(null::public.ayngaran_settings, coalesce(p_changes->'settings','[]'::jsonb)) r
on conflict ("owner_id") do update set "position"=excluded."position","extras"=excluded."extras","name"=excluded."name","address"=excluded."address","phone"=excluded."phone","currency"=excluded."currency","receipt_note"=excluded."receipt_note","tax_rate"=excluded."tax_rate"
where (existing."position",existing."extras",existing."name",existing."address",existing."phone",existing."currency",existing."receipt_note",existing."tax_rate") is distinct from (excluded."position",excluded."extras",excluded."name",excluded."address",excluded."phone",excluded."currency",excluded."receipt_note",excluded."tax_rate");
insert into public.ayngaran_villages as existing ("owner_id","position","extras","name")
select p_owner,r."position",r."extras",r."name" from jsonb_populate_recordset(null::public.ayngaran_villages, coalesce(p_changes->'villages','[]'::jsonb)) r
on conflict ("owner_id","name") do update set "position"=excluded."position","extras"=excluded."extras"
where (existing."position",existing."extras") is distinct from (excluded."position",excluded."extras");
insert into public.ayngaran_products as existing ("owner_id","position","extras","id","name","tamil","category","sku","barcode","price","cost","unit","reorder","art","active")
select p_owner,r."position",r."extras",r."id",r."name",r."tamil",r."category",r."sku",r."barcode",r."price",r."cost",r."unit",r."reorder",r."art",r."active" from jsonb_populate_recordset(null::public.ayngaran_products, coalesce(p_changes->'products','[]'::jsonb)) r
