where (existing."position",existing."extras",existing."name",existing."phone",existing."address",existing."village",existing."code",existing."opening_balance",existing."credit_limit") is distinct from (excluded."position",excluded."extras",excluded."name",excluded."phone",excluded."address",excluded."village",excluded."code",excluded."opening_balance",excluded."credit_limit");
