where (existing."position",existing."extras",existing."product_id",existing."quantity") is distinct from (excluded."position",excluded."extras",excluded."product_id",excluded."quantity");
insert into public.ayngaran_price_history as existing ("owner_id","position","extras","id","product_id","date","old_price","new_price","old_cost","new_cost","reason")
select p_owner,r."position",r."extras",r."id",r."product_id",r."date",r."old_price",r."new_price",r."old_cost",r."new_cost",r."reason" from jsonb_populate_recordset(null::public.ayngaran_price_history, coalesce(p_changes->'price_history','[]'::jsonb)) r
on conflict ("owner_id","id") do update set "position"=excluded."position","extras"=excluded."extras","product_id"=excluded."product_id","date"=excluded."date","old_price"=excluded."old_price","new_price"=excluded."new_price","old_cost"=excluded."old_cost","new_cost"=excluded."new_cost","reason"=excluded."reason"
where (existing."position",existing."extras",existing."product_id",existing."date",existing."old_price",existing."new_price",existing."old_cost",existing."new_cost",existing."reason") is distinct from (excluded."position",excluded."extras",excluded."product_id",excluded."date",excluded."old_price",excluded."new_price",excluded."old_cost",excluded."new_cost",excluded."reason");
delete from public.ayngaran_held_bills where owner_id=p_owner and id in (select jsonb_array_elements_text(coalesce(p_changes->'deleted_held','[]'::jsonb)));
end; $$;
create or replace view ayngaran_private.settings_json with (security_invoker=true) as select t.owner_id, t.position, 'settings'::text as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('name',t."name",'address',t."address",'phone',t."phone",'currency',t."currency",'receiptNote',t."receipt_note",'taxRate',t."tax_rate")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_settings t;
create or replace view ayngaran_private.villages_json with (security_invoker=true) as select t.owner_id, t.position, t."name" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('name',t."name")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_villages t;
create or replace view ayngaran_private.products_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'name',t."name",'tamil',t."tamil",'category',t."category",'sku',t."sku",'barcode',t."barcode",'price',t."price",'cost',t."cost",'unit',t."unit",'reorder',t."reorder",'art',t."art",'active',t."active")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_products t;
create or replace view ayngaran_private.product_images_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'image',t."image")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_product_images t;
create or replace view ayngaran_private.inventory_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'stock',t."stock")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_inventory t;
create or replace view ayngaran_private.customers_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'name',t."name",'phone',t."phone",'address',t."address",'village',t."village",'code',t."code",'openingBalance',t."opening_balance",'creditLimit',t."credit_limit")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_customers t;
create or replace view ayngaran_private.suppliers_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'name',t."name",'phone',t."phone",'address',t."address",'village',t."village",'code',t."code",'openingBalance',t."opening_balance")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_suppliers t;
create or replace view ayngaran_private.sales_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'number',t."number",'date',to_char(t."date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'customerId',t."customer_id",'customerName',t."customer_name",'customerCode',t."customer_code",'customerVillage',t."customer_village",'seller',t."seller",'subtotal',t."subtotal",'discount',t."discount",'tax',t."tax",'total',t."total",'paid',t."paid",'method',t."method",'tendered',t."tendered",'change',t."change",'void',t."void",'voidReason',t."void_reason",'voidDate',to_char(t."void_date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_sales t;
create or replace view ayngaran_private.sale_items_json with (security_invoker=true) as select t.owner_id, t.position, t.parent_id, t.line_no, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('productId',t."product_id",'name',t."name",'tamil',t."tamil",'sku',t."sku",'unit',t."unit",'quantity',t."quantity",'price',t."price",'cost',t."cost")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_sale_items t;
create or replace view ayngaran_private.purchases_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'supplierId',t."supplier_id",'reference',t."reference",'paid',t."paid",'date',to_char(t."date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'total',t."total",'number',t."number")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_purchases t;
create or replace view ayngaran_private.purchase_items_json with (security_invoker=true) as select t.owner_id, t.position, t.parent_id, t.line_no, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('productId',t."product_id",'name',t."name",'sku',t."sku",'unit',t."unit",'quantity',t."quantity",'cost',t."cost",'sellingPrice',t."selling_price",'total',t."total")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_purchase_items t;
create or replace view ayngaran_private.payments_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'customerId',t."customer_id",'supplierId',t."supplier_id",'amount',t."amount",'note',t."note",'date',to_char(t."date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_payments t;
create or replace view ayngaran_private.stock_movements_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'productId',t."product_id",'quantity',t."quantity",'type',t."type",'reference',t."reference",'date',to_char(t."date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_stock_movements t;
create or replace view ayngaran_private.held_bills_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'customerId',t."customer_id",'discount',t."discount",'label',t."label",'date',to_char(t."date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_held_bills t;
create or replace view ayngaran_private.held_bill_items_json with (security_invoker=true) as select t.owner_id, t.position, t.parent_id, t.line_no, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('productId',t."product_id",'quantity',t."quantity")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_held_bill_items t;
create or replace view ayngaran_private.price_history_json with (security_invoker=true) as select t.owner_id, t.position, t."id" as id, t.extras || coalesce((select jsonb_object_agg(k,v) from jsonb_each(jsonb_build_object('id',t."id",'productId',t."product_id",'date',to_char(t."date" at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'oldPrice',t."old_price",'newPrice',t."new_price",'oldCost',t."old_cost",'newCost',t."new_cost",'reason',t."reason")) x(k,v) where v <> 'null'::jsonb),'{}'::jsonb) as data from public.ayngaran_price_history t;
create or replace function ayngaran_private.read_state(p_owner uuid) returns jsonb language sql stable security invoker set search_path='' as $$ select coalesce((select state_extras from public.ayngaran_stores where owner_id=p_owner),'{}'::jsonb) || jsonb_build_object(
'settings',(select data from ayngaran_private.settings_json v where v.owner_id=p_owner),
'villages',(select coalesce(jsonb_agg(v.data->'name' order by v.position,v.id),'[]'::jsonb) from ayngaran_private.villages_json v where v.owner_id=p_owner),
'products',(select coalesce(jsonb_agg(v.data || jsonb_build_object('stock',i.stock,'image',coalesce(img.image,'')) order by v.position,v.id),'[]'::jsonb) from ayngaran_private.products_json v join public.ayngaran_inventory i on i.owner_id=v.owner_id and i.id=v.id left join public.ayngaran_product_images img on img.owner_id=v.owner_id and img.id=v.id where v.owner_id=p_owner),
'customers',(select coalesce(jsonb_agg(v.data order by v.position,v.id),'[]'::jsonb) from ayngaran_private.customers_json v where v.owner_id=p_owner),
'suppliers',(select coalesce(jsonb_agg(v.data order by v.position,v.id),'[]'::jsonb) from ayngaran_private.suppliers_json v where v.owner_id=p_owner),
'sales',(select coalesce(jsonb_agg(v.data || jsonb_build_object('items', (select coalesce(jsonb_agg(l.data order by l.line_no),'[]'::jsonb) from ayngaran_private.sale_items_json l where l.owner_id=p_owner and l.parent_id=v.id)) order by v.position,v.id),'[]'::jsonb) from ayngaran_private.sales_json v where v.owner_id=p_owner),
'purchases',(select coalesce(jsonb_agg(v.data || jsonb_build_object('items', (select coalesce(jsonb_agg(l.data order by l.line_no),'[]'::jsonb) from ayngaran_private.purchase_items_json l where l.owner_id=p_owner and l.parent_id=v.id)) order by v.position,v.id),'[]'::jsonb) from ayngaran_private.purchases_json v where v.owner_id=p_owner),
'payments',(select coalesce(jsonb_agg(v.data order by v.position,v.id),'[]'::jsonb) from ayngaran_private.payments_json v where v.owner_id=p_owner),
'movements',(select coalesce(jsonb_agg(v.data order by v.position,v.id),'[]'::jsonb) from ayngaran_private.stock_movements_json v where v.owner_id=p_owner),
'held',(select coalesce(jsonb_agg(v.data || jsonb_build_object('items', (select coalesce(jsonb_agg(l.data order by l.line_no),'[]'::jsonb) from ayngaran_private.held_bill_items_json l where l.owner_id=p_owner and l.parent_id=v.id)) order by v.position,v.id),'[]'::jsonb) from ayngaran_private.held_bills_json v where v.owner_id=p_owner),
'priceHistory',(select coalesce(jsonb_agg(v.data order by v.position,v.id),'[]'::jsonb) from ayngaran_private.price_history_json v where v.owner_id=p_owner)); $$;
create or replace function public.ayngaran_load_v2(p_initial jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare current_store public.ayngaran_stores;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 insert into public.ayngaran_stores(owner_id,state) values(auth.uid(),p_initial) on conflict(owner_id) do nothing;
 select * into current_store from public.ayngaran_stores where owner_id=auth.uid() for update;
 if current_store.schema_version=1 then
  perform ayngaran_private.write_rows(auth.uid(),ayngaran_private.legacy_rows(current_store.state));
  update public.ayngaran_stores set schema_version=2,state_extras=current_store.state - array['settings','villages','products','customers','suppliers','sales','purchases','payments','movements','held','priceHistory']::text[] where owner_id=auth.uid();
 end if;
 return jsonb_build_object('state',ayngaran_private.read_state(auth.uid()),'revision',current_store.revision,'storageVersion',2);
end; $$;
create or replace function public.ayngaran_commit_v2(p_revision bigint,p_request_id uuid,p_changes jsonb,p_result jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare current_store public.ayngaran_stores; prior jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into current_store from public.ayngaran_stores where owner_id=auth.uid() for update;
 if not found or current_store.schema_version<>2 then raise exception 'Initialize relational store first'; end if;
 select result into prior from public.ayngaran_requests where owner_id=auth.uid() and request_id=p_request_id;
 if found then return jsonb_build_object('state',ayngaran_private.read_state(auth.uid()),'revision',current_store.revision,'result',prior,'storageVersion',2); end if;
 if current_store.revision<>p_revision then return jsonb_build_object('conflict',true); end if;
 perform ayngaran_private.write_rows(auth.uid(),p_changes);
 update public.ayngaran_stores set revision=revision+1,updated_at=now(),state_extras=coalesce(p_changes->'_state_extras',state_extras) where owner_id=auth.uid();
 insert into public.ayngaran_requests(owner_id,request_id,result,action_type) values(auth.uid(),p_request_id,p_result,p_changes->>'_action');
 return jsonb_build_object('state',ayngaran_private.read_state(auth.uid()),'revision',p_revision+1,'result',p_result,'storageVersion',2);
end; $$;
-- Serialize backfill against existing writes. Any constraint failure rolls back
-- this entire migration, including schema changes, leaving the old data intact.
lock table public.ayngaran_stores in share row exclusive mode;
do $$ declare s record; begin
 for s in select owner_id,state from public.ayngaran_stores where schema_version=1 for update loop
  perform ayngaran_private.write_rows(s.owner_id,ayngaran_private.legacy_rows(s.state));
  update public.ayngaran_stores set schema_version=2,state_extras=s.state - array['settings','villages','products','customers','suppliers','sales','purchases','payments','movements','held','priceHistory']::text[] where owner_id=s.owner_id;
 end loop;
end; $$;
-- Block old application versions from writing stale JSON after the upgrade.
create or replace function public.ayngaran_commit(p_revision bigint,p_request_id uuid,p_state jsonb,p_result jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $$ begin
 raise exception 'Database upgraded. Restart the updated application before saving.' using errcode='55000';
end; $$;
revoke all on all functions in schema ayngaran_private from public,anon;
grant execute on all functions in schema ayngaran_private to authenticated;
revoke all on all tables in schema ayngaran_private from public,anon,authenticated;
grant select on all tables in schema ayngaran_private to authenticated;
revoke all on function public.ayngaran_load_v2(jsonb), public.ayngaran_commit_v2(bigint,uuid,jsonb,jsonb) from public,anon;
grant execute on function public.ayngaran_load_v2(jsonb), public.ayngaran_commit_v2(bigint,uuid,jsonb,jsonb) to authenticated;
-- Reporting views avoid duplicating mutable customer/supplier balances.
create or replace view public.ayngaran_customer_balances with (security_invoker=true) as
select c.owner_id,c.id,c.name,c.opening_balance
 + coalesce((select sum(s.total-s.paid) from public.ayngaran_sales s where s.owner_id=c.owner_id and s.customer_id=c.id and not coalesce(s.void,false)),0)
 - coalesce((select sum(p.amount) from public.ayngaran_payments p where p.owner_id=c.owner_id and p.customer_id=c.id),0) as balance
from public.ayngaran_customers c;
create or replace view public.ayngaran_supplier_balances with (security_invoker=true) as
select c.owner_id,c.id,c.name,c.opening_balance
 + coalesce((select sum(s.total-s.paid) from public.ayngaran_purchases s where s.owner_id=c.owner_id and s.supplier_id=c.id),0)
 - coalesce((select sum(p.amount) from public.ayngaran_payments p where p.owner_id=c.owner_id and p.supplier_id=c.id),0) as balance
from public.ayngaran_suppliers c;
create or replace view public.ayngaran_daily_sales with (security_invoker=true) as
select s.owner_id,(s.date at time zone 'Asia/Colombo')::date as sale_day,
 count(*) as bill_count,sum(s.total) as sales,sum(s.paid) as collected_on_bills,sum(s.total-s.paid) as credit_issued,
 sum(s.subtotal-s.discount-coalesce((select sum(round(i.quantity*i.cost,2)) from public.ayngaran_sale_items i where i.owner_id=s.owner_id and i.parent_id=s.id),0)) as gross_profit
from public.ayngaran_sales s where not coalesce(s.void,false) group by s.owner_id,(s.date at time zone 'Asia/Colombo')::date;
revoke all on public.ayngaran_customer_balances,public.ayngaran_supplier_balances,public.ayngaran_daily_sales from public,anon;
grant select on public.ayngaran_customer_balances,public.ayngaran_supplier_balances,public.ayngaran_daily_sales to authenticated;
notify pgrst, 'reload schema';
commit;
